<script>import "./orders.remote";import "./extra.remote";import {onMount,tick} from 'svelte';import {refreshAll} from '$app/navigation';let {data}=$props();let draft=$state('');let count=$state(0);let hydrated=$state(false);let notices=$state(0);let status=$state('Ready');let documentID=$state('');onMount(()=>{hydrated=true;documentID=window.__qualificationDocument??=crypto.randomUUID();window.__qualificationRefresh=async(event)=>{notices++;if(event.error){status=event.error;return};await refreshAll();await tick();status='Ready '+data.order.total;};});</script><h1>Order total {data.order.total}</h1><input id="draft" bind:value={draft}/><button onclick={()=>count++}>Increment</button><p>Count {count}</p><p>Hydrated {String(hydrated)}</p><p>Notices {notices}</p><p>{status}</p><p>Document {documentID}</p><p>Again {data.order.again}; initialized {data.order.initializations}; quantity {data.order.quantity}</p>{#if data.fetched}<p>Fetched {data.fetched}</p>{/if}{#await data.later}<p>Waiting</p>{:then value}<p>Deferred {value}</p>{/await}